      ro: ["A fost primul parc național declarat în Coreea (1967).", "Vârful Cheonwangbong are 1.915 metri altitudine.", "Suprafața parcului este de aproximativ 483 km².", "Găzduiește un program de protecție a ursului negru asiatic.", "Există peste 4.900 de specii înregistrate în ecosistem.", "Cuprinde numeroase situri de patrimoniu cultural național."],
      en: ["Established in 1967 as Korea's very first national park.", "Cheonwangbong (1,915m) is the highest mainland peak.", "Covers an expansive area of 483 square kilometers.", "Home to a major Asiatic black bear restoration project.", "Contains seven primary ancient Buddhist temples.", "Features more than 4,900 distinct biological species."],
