      en: ["Total length of 521 kilometers", "Basin area of 23,384 square kilometers", "Discharges into the Korea Strait at Busan", "Source is the Hwangji Pond in Taebaek", "Forms the 1950 Pusan Perimeter defense line", "Primary water source for 10 million people"],
      es: ["Longitud: 525 km", "Cuenca: 23.384 km²", "Desembocadura: Estrecho de Corea cerca de Busan", "Uso agrícola: 60 % del agua para riego", "Humedal Upo: 8,5 km², sitio Ramsar desde 1998", "Centrales hidroeléctricas: 3 a lo largo del río"],
