      fr: ["Longueur : 525 km", "Bassin versant : 23 384 km²", "Embouchure : Détroit de Corée près de Busan", "Usage agricole : 60 % de l'eau pour l'irrigation", "Zone humide d'Upo : 8,5 km², site Ramsar depuis 1998", "Centrales hydroélectriques : 3 le long du fleuve"],
