      ro: ["Deschis în martie 2006", "Suprafață totală de 185.124 m²", "Sălcii cu o vechime de peste 400 de ani", "Peste 65.000 de flori plantate anual", "Punct de acces către Muntele Mudeungsan", "Habitat protejat pentru pescărușul albastru"],
      en: ["Opened in March 2006", "Total area of 185,124 square meters", "Home to 400-year-old willow trees", "Over 65,000 seasonal flowers planted", "Adjacent to Mudeungsan National Park", "Critical habitat for the common kingfisher"],
      es: ["Superficie: 0,8 km²", "Año de construcción: 1976", "Altura de la presa: 30 m", "Especies de aves migratorias: más de 50", "Parque ecológico desde 2015", "Longitud del sendero: 4,5 km"],
      pt: ["Superfície: 0,8 km²", "Ano de construção: 1976", "Altura da barragem: 30 m", "Espécies de aves migratórias: mais de 50", "Parque ecológico desde 2015", "Comprimento do trilho: 4,5 km"],
