    facts: {
      de: ["Der Beopjusa-Tempel beherbergt eine riesige vergoldete Buddha-Statue aus Bronze.", "Der Hauptgipfel ist Cheonwangbong (1.058 m).", "Spektakuläre Felsformationen und tiefe Täler.", "Ein beliebtes Wanderziel im Herbst."],
      hu: ["A Beopjusa-templom egy hatalmas aranyozott bronz Buddha-szobornak ad otthont.", "A fő csúcs a Cheonwangbong (1058 m).", "Látványos sziklaalakzatok és mély völgyek.", "Népszerű túracélpont ősszel."],
      ro: ["Templul Beopjusa găzduiește o statuie uriașă de Buddha din bronz aurit.", "Vârful principal este Cheonwangbong (1.058 m).", "Formațiuni stâncoase spectaculoase și văi adânci.", "O destinație populară pentru drumeții toamna."],
      en: ["Beopjusa Temple houses a massive gilt-bronze Buddha statue.", "The main peak is Cheonwangbong (1,058m).", "Spectacular rock formations and deep valleys.", "A popular hiking destination in autumn."],
      es: ["El templo Beopjusa alberga una enorme estatua de Buda de bronce dorado.", "El pico principal es Cheonwangbong (1.058 m).", "Formaciones rocosas espectaculares y valles profundos.", "Un destino de senderismo popular en otoño."],
      pt: ["O Templo Beopjusa abriga uma enorme estátua de Buda de bronze dourado.", "O pico principal é Cheonwangbong (1.058 m).", "Formações rochosas espetaculares e vales profundos.", "Um destino popular de caminhadas no outono."],
      fr: ["Le temple Beopjusa abrite une immense statue de Bouddha en bronze doré.", "Le sommet principal est Cheonwangbong (1 058 m).", "Formations rocheuses spectaculaires et vallées profondes.", "Une destination de randonnée prisée en automne."],
    }, image: "/poi-images/sogni-mountain-nature-v2.webp",
    descriptionAdvanced: {
      de: "Das Sogni-Gebirge, auch bekannt als Songnisan, ist ein bedeutender Gebirgszug im Zentrum Südkoreas und wurde 1970 zum Nationalpark erklärt. Die höchste Erhebung ist der Cheonwangbong mit 1.058 Metern über dem Meeresspiegel. Das Gebirge besteht überwiegend aus Granitformationen, die durch Erosion markante Gipfel und tiefe Täler gebildet haben. Historisch ist das Gebiet eng mit dem Buddhismus verbunden; hier befindet sich der Beopjusa-Tempel, der im Jahr 553 gegründet wurde und das UNESCO-Welterbe 'Sansa' beherbergt. Besonders sehenswert ist die dortige goldene Buddha-Statue, die mit 33 Metern eine der größten ihrer Art ist. Songnisan ist zudem bekannt für seine dichten Kiefernwälder, insbesondere die 'Jeongipum-Kiefer', die als Naturdenkmal Nr. 103 registriert ist und eine legendäre Geschichte als Berater des Königs besitzt. Das Ökosystem beherbergt seltene Tierarten wie den Amur-Goral und den Schwarzspecht.",
      hu: "A Sogni-hegység, más néven Songnisan, Dél-Korea középső részén fekvő jelentős hegyvonulat, amelyet 1970-ben nyilvánítottak nemzeti parkká. Legmagasabb csúcsa a Cheonwangbong, amely 1058 méterrel magasodik a tengerszint fölé. A hegység szerkezetét főként gránit határozza meg, amely az erózió hatására látványos sziklacsúcsokat és mély völgyeket formált. A terület történelmileg szorosan kötődik a buddhizmushoz; itt található az 553-ban alapított Beopjusa-templom, amely az UNESCO Világörökség részét képezi. A templomban látható a 33 méter magas arany Buddha-szobor, amely az egyik legnagyobb ilyen alkotás a világon. Songnisan híres sűrű fenyőerdőiről is, különösen a 'Jeongipum' fenyőről, amely hivatalos természetvédelmi emlék. Az ökoszisztéma olyan ritka fajoknak ad otthont, mint az amuri gorál és a fekete harkály.",
      ro: "Muntele Sogni, cunoscut sub numele de Songnisan, este un lanț muntos proeminent situat în centrul Coreei de Sud și a fost declarat parc național în anul 1970. Cel mai înalt vârf este Cheonwangbong, atingând o altitudine de 1.058 de metri. Masivul este compus în principal din formațiuni de granit care, prin eroziune, au creat vârfuri ascuțite și văi adânci spectaculoase. Din punct de vedere istoric, zona este strâns legată de budism, găzduind templul Beopjusa, fondat în anul 553 și inclus în Patrimoniul Mondial UNESCO. Templul deține o statuie de aur a lui Buddha înaltă de 33 de metri, una dintre cele mai mari din lume. Songnisan este, de asemenea, renumit pentru pădurile sale de pini, în special pinul 'Jeongipum', monument natural cu un rang nobiliar legendar. Ecosistemul parcului protejează specii rare precum goralul de Amur și ciocănitoarea neagră.",
      en: "Songnisan Mountain, located in central South Korea, is a prominent peak and was designated as a national park in 1970. Its highest point is Cheonwangbong, reaching 1,058 meters above sea level. The mountain is primarily composed of granite formations that have eroded over millennia to create sharp peaks and deep valleys. Historically, the area is a center of Korean Buddhism, home to the Beopjusa Temple, which was founded in 553 AD and is a UNESCO World Heritage site. The temple features a massive 33-meter gold Buddha statue, one of the largest in Asia. Songnisan is also famous for its ancient pine forests, including the legendary 'Jeongipum Pine,' which holds a unique honorary title from a Joseon king. The park's ecosystem supports rare wildlife such as the Amur goral and the black woodpecker.",
      es: "Songnisan (literalmente 'montaña de estancia eterna') es una montaña de 1.058 m de altura en la provincia de Chungcheongbuk-do, en el centro del Parque Nacional Songnisan. El parque es famoso por el templo Beopjusa, uno de los templos budistas más antiguos de Corea (fundado en 553 d.C.). La montaña se caracteriza por formaciones rocosas de granito, incluida la estatua de Buda Mireuk de 33 m de altura. La flora incluye 500 especies de plantas, incluidas orquídeas raras. El parque nacional es Reserva de la Biosfera de la UNESCO.",
      pt: "O Songnisan (literalmente 'montanha da estadia eterna') é uma montanha com 1.058 m de altitude na província de Chungcheongbuk-do, no centro do Parque Nacional de Songnisan. O parque é famoso pelo Templo Beopjusa, um dos templos budistas mais antigos da Coreia (fundado em 553 d.C.). A montanha é caracterizada por formações rochosas de granito, incluindo a estátua de Buda Mireuk com 33 m de altura. A flora inclui 500 espécies de plantas, incluindo orquídeas raras. O parque nacional é uma Reserva da Biosfera da UNESCO.",
      fr: "Le Songnisan (littéralement 'montagne du séjour éternel') est une montagne de 1 058 m d'altitude située dans la province de Chungcheongbuk-do, au centre du parc national de Songnisan. Le parc est célèbre pour le temple Beopjusa, l'un des plus anciens temples bouddhistes de Corée (fondé en 553 apr. J.-C.). La montagne se caractérise par des formations rocheuses en granit, dont la statue de Bouddha Mireuk haute de 33 m. La flore comprend 500 espèces de plantes, dont des orchidées rares. Le parc national est une réserve de biosphère de l'UNESCO.",
    },
