      de: ["Höchster Gipfel: Cheonwangbong (1.058 m)", "Nationalpark-Status seit 1970", "Gründungsjahr von Beopjusa: 553 n. Chr.", "33 Meter hohe Buddha-Statue", "Jeongipum-Kiefer ist ca. 600 Jahre alt", "Gesamtfläche des Parks: 274,5 km²"],
      hu: ["Legmagasabb csúcs: Cheonwangbong (1058 m)", "1970 óta nemzeti park", "Beopjusa-templom alapítása: i.sz. 553", "33 méter magas arany Buddha-szobor", "A Jeongipum fenyő kb. 600 éves", "A park teljes területe: 274,5 km²"],
      ro: ["Vârful maxim: Cheonwangbong (1.058 m)", "Statut de parc național din 1970", "Templul Beopjusa fondat în anul 553", "Statuie de aur a lui Buddha de 33 m", "Pinul Jeongipum are peste 600 de ani", "Suprafața totală a parcului: 274,5 km²"],
      en: ["Highest peak: Cheonwangbong (1,058 m)", "National Park designation: 1970", "Beopjusa Temple founded in 553 AD", "33-meter tall golden Buddha statue", "Jeongipum Pine is over 600 years old", "Total park area: 274.5 square kilometers"],
      es: ["Altura: 1.058 m", "Parque nacional desde 1970", "Fundación del templo: 553 d.C.", "Altura del Buda Mireuk: 33 m", "Reserva de la Biosfera de la UNESCO desde 1982", "Especies de plantas: 500"],
      pt: ["Altitude: 1.058 m", "Parque nacional desde 1970", "Fundação do templo: 553 d.C.", "Altura do Buda Mireuk: 33 m", "Reserva da Biosfera da UNESCO desde 1982", "Espécies de plantas: 500"],
      fr: ["Altitude : 1 058 m", "Parc national depuis 1970", "Fondation du temple : 553 apr. J.-C.", "Hauteur du Bouddha Mireuk : 33 m", "Réserve de biosphère de l'UNESCO depuis 1982", "Espèces végétales : 500"],
