      en: ["Opened on June 18, 2005", "Total area of 1.16 square kilometers", "Divided into 5 thematic zones", "Home to approx. 400,000 trees", "Over 100 bird species recorded", "Site of Seoul's first waterworks (1908)"],
      es: ["Superficie: 1,16 km²", "Apertura: 2005", "Visitantes anuales: aprox. 10 millones", "Áreas temáticas: 5", "Especies animales en el recinto: 3 (ciervos, corzos, alces)", "Número de árboles: más de 400.000"],
