      fr: ["Superficie : 1,16 km²", "Ouverture : 2005", "Visiteurs annuels : env. 10 millions", "Zones thématiques : 5", "Espèces animales dans l'enclos : 3 (cerfs, chevreuils, élans)", "Nombre d'arbres : plus de 400 000"],
