    facts: {
      de: ["Der Kkotji-Strand ist berühmt für seine Sonnenuntergänge.", "Der Anmyeondo-Freizeitwald hat einzigartige Kiefern aus der Goryeo-Zeit.", "Ursprünglich eine Halbinsel, die durch einen Kanal getrennt wurde.", "Ein Hauptproduzent von Meersalz."],
      hu: ["A Kkotji strand híres naplementéiről.", "Az Anmyeondo rekreációs erdőben egyedi, Goryeo-kori fenyők találhatók.", "Eredetileg egy félsziget volt, amelyet egy csatorna választott el.", "A tengeri só egyik fő termelője."],
      ro: ["Plaja Kkotji este renumită pentru apusurile sale.", "Pădurea de agrement Anmyeondo are pini unici din perioada Goryeo.", "Inițial o peninsulă, a fost separată de un canal.", "Un producător major de sare de mare."],
      en: ["Kkotji Beach is famous for its sunsets.", "Anmyeondo Recreational Forest has unique pine trees dating back to the Goryeo dynasty.", "Originally a peninsula, it was separated by a canal.", "A major producer of sea salt."],
      es: ["La playa Kkotji es famosa por sus atardeceres.", "El bosque recreativo de Anmyeondo tiene pinos únicos de la era Goryeo.", "Originalmente una península separada por un canal.", "Un importante productor de sal marina."],
      pt: ["A praia Kkotji é famosa pelos seus pores do sol.", "A floresta recreativa de Anmyeondo tem pinheiros únicos da era Goryeo.", "Originalmente uma península separada por um canal.", "Um importante produtor de sal marinho."],
      fr: ["La plage de Kkotji est célèbre pour ses couchers de soleil.", "La forêt récréative d'Anmyeondo possède des pins uniques de l'ère Goryeo.", "À l'origine une péninsule séparée par un canal.", "Un important producteur de sel marin."],
    }, image: "/poi-images/anmyeon-island-nature-v2.webp",
    descriptionAdvanced: {
      de: "Anmyeondo ist die sechstgrößte Insel Südkoreas und liegt im Landkreis Taean in der Provinz Chungcheongnam-do. Ursprünglich war das Gebiet eine Halbinsel, wurde jedoch während der Joseon-Dynastie durch den Bau eines Kanals zur Insel umgewandelt, um den Seetransport von Steuergetreide zu erleichtern. Seit 1970 ist die Insel durch eine Brücke mit dem Festland verbunden. Anmyeondo ist weltbekannt für seinen Anmyeonsong-Kiefernwald, der aus über 100 Jahre alten roten Kiefern besteht, die früher ausschließlich für den Bau von königlichen Palästen und Schiffen verwendet wurden. Die Insel beherbergt auch den Taeanhaean-Nationalpark, der für seine ausgedehnten Sandstrände wie Kkotji Beach bekannt ist. Die Küstenlandschaft ist durch Gezeitenflächen geprägt, die ein reiches Ökosystem für Meereslebewesen bieten. Heute ist die Insel ein Zentrum für Biodiversität und Naturschutz, wobei der Kiefernwald als staatliches Schutzgebiet verwaltet wird.",
      hu: "Anmyeondo Dél-Korea hatodik legnagyobb szigete, amely Taean megyében, Chungcheongnam-do tartományban található. Eredetileg félsziget volt, de a Csoszon-dinasztia idején egy csatorna építésével szigetté alakították, hogy megkönnyítsék az adóként beszedett gabona tengeri szállítását. 1970 óta híd köti össze a szárazfölddel. Anmyeondo világszerte ismert az 'Anmyeonsong' fenyőerdőjéről, amely több mint 100 éves vörösfenyőkből áll; ezeket korábban kizárólag királyi paloták és hajók építésére használták. A szigeten található a Taeanhaean Nemzeti Park is, amely kiterjedt homokos strandjairól, például a Kkotji-partról nevezetes. A tengerparti tájat az árapály-síkságok határozzák meg, amelyek gazdag élőhelyet biztosítanak a tengeri élőlényeknek. Napjainkban a sziget a biológiai sokféleség és a természetvédelem központja, a fenyőerdő pedig állami védelem alatt áll.",
      ro: "Anmyeondo este a șasea insulă ca mărime din Coreea de Sud, situată în districtul Taean din provincia Chungcheongnam-do. Inițial o peninsulă, a fost transformată în insulă în timpul dinastiei Joseon prin construcția unui canal pentru a facilita transportul maritim al cerealelor colectate ca taxe. Din 1970, insula este conectată de continent printr-un pod. Anmyeondo este celebră la nivel mondial pentru pădurea de pini 'Anmyeonsong', compusă din pini roșii de peste 100 de ani, folosiți în trecut exclusiv pentru construcția palatelor regale și a navelor. Insula găzduiește, de asemenea, Parcul Național Taeanhaean, cunoscut pentru plajele sale întinse de nisip, precum plaja Kkotji. Peisajul costier este definit de zonele intertidale care oferă un ecosistem bogat pentru fauna marină. Astăzi, insula este un centru de biodiversitate, pădurea de pini fiind administrată ca rezervație de stat.",
      en: "Anmyeondo is South Korea's sixth-largest island, located in Taean County, Chungcheongnam-do province. Originally a peninsula, it was converted into an island during the Joseon Dynasty through the excavation of a canal to facilitate the maritime transport of tax grain. Since 1970, it has been connected to the mainland by a bridge. Anmyeondo is world-famous for its 'Anmyeonsong' pine forest, consisting of red pines over 100 years old that were historically reserved for building royal palaces and naval vessels. The island is also home to the Taeanhaean National Park, noted for its expansive sandy beaches such as Kkotji Beach. The coastal landscape is characterized by tidal flats that provide a rich habitat for marine biodiversity. Today, the island serves as a major hub for conservation, with its pine forests managed as a protected state asset.",
      es: "La isla Anmyeon se encuentra frente a la costa oeste de Corea del Sur, en la provincia de Chungcheongnam-do. Es la sexta isla más grande del país y tiene una superficie de 113,7 km². La isla está conectada al continente por un puente. Es famosa por sus largas playas de arena, especialmente la playa Kkotji, y sus bosques de pinos. El pino Anmyeon (Pinus densiflora) es una subespecie local utilizada para el barniz Ssanghwa. La isla alberga el Bosque Recreativo Natural de Anmyeon-do. La pesca y el turismo son sectores económicos importantes.",
      pt: "A ilha Anmyeon está localizada ao largo da costa oeste da Coreia do Sul, na província de Chungcheongnam-do. É a sexta maior ilha do país e tem uma área de 113,7 km². A ilha está ligada ao continente por uma ponte. É famosa pelas suas longas praias de areia, especialmente a praia Kkotji, e pelas suas florestas de pinheiros. O pinheiro Anmyeon (Pinus densiflora) é uma subespécie local utilizada para o verniz Ssanghwa. A ilha abriga a Floresta Recreativa Natural de Anmyeon-do. A pesca e o turismo são setores econômicos importantes.",
      fr: "L'île Anmyeon est située au large de la côte ouest de la Corée du Sud, dans la province de Chungcheongnam-do. C'est la sixième plus grande île du pays et elle a une superficie de 113,7 km². L'île est reliée au continent par un pont. Elle est célèbre pour ses longues plages de sable, notamment la plage de Kkotji, et ses forêts de pins. Le pin Anmyeon (Pinus densiflora) est une sous-espèce locale utilisée pour le vernis Ssanghwa. L'île abrite la forêt récréative naturelle d'Anmyeon-do. La pêche et le tourisme sont des secteurs économiques importants.",
    },
