    image: "/poi-images/woopo-wetland-nature-v2.webp",
    description: {
      de: "Das größte natürliche Binnenfeuchtgebiet in Südkorea. Es ist ein Paradies für seltene Pflanzen, Vögel und andere Wildtiere.",
      hu: "Dél-Korea legnagyobb természetes beltéri vizes élőhelye. Ritka növények, madarak és más vadon élő állatok paradicsoma.",
      ro: "Cea mai mare zonă umedă interioară naturală din Coreea de Sud. Este un paradis pentru plante rare, păsări și alte viețuitoare sălbatice.",
      en: "The largest natural inland wetland in South Korea. It is a haven for rare plants, birds, and other wildlife.",
      es: "El humedal interior natural más grande de Corea del Sur. Es un paraíso para plantas raras, aves y otros animales salvajes.",
      pt: "A maior zona húmida interior natural da Coreia do Sul. É um paraíso para plantas raras, aves e outros animais selvagens.",
      fr: "La plus grande zone humide intérieure naturelle de Corée du Sud. C'est un paradis pour les plantes rares, les oiseaux et autres animaux sauvages.",
    },
    facts: {
      de: ["Ein von Ramsar ausgewiesenes Feuchtgebiet.", "Gegründet vor über 140 Millionen Jahren.", "Beherbergt den gefährdeten eurasischen Löffler.", "Besucher können das Gebiet zu Fuß oder mit dem Fahrrad erkunden."],
      hu: ["Ramsari egyezmény által védett vizes élőhely.", "Több mint 140 millió évvel ezelőtt alakult ki.", "Otthont ad a veszélyeztetett kanalasgémnek.", "A látogatók gyalog vagy kerékpárral fedezhetik fel a területet."],
      ro: ["O zonă umedă desemnată Ramsar.", "Formată acum peste 140 de milioane de ani.", "Găzduiește lopătarul eurasian, o specie pe cale de dispariție.", "Vizitatorii pot explora zona pe jos sau cu bicicleta."],
      en: ["A Ramsar designated wetland.", "Formed over 140 million years ago.", "Home to the endangered Eurasian Spoonbill.", "Visitors can explore the area on foot or by bicycle."],
      es: ["Un humedal designado por Ramsar.", "Fundado hace más de 140 millones de años.", "Alberga la espátula euroasiática en peligro de extinción.", "Los visitantes pueden explorar la zona a pie o en bicicleta."],
      pt: ["Uma zona húmida designada pela Ramsar.", "Fundada há mais de 140 milhões de anos.", "Abriga o colhereiro euro-asiático ameaçado.", "Os visitantes podem explorar a área a pé ou de bicicleta."],
      fr: ["Une zone humide désignée par Ramsar.", "Fondée il y a plus de 140 millions d'années.", "Abrite la spatule blanche menacée.", "Les visiteurs peuvent explorer la zone à pied ou à vélo."],
    },
    descriptionAdvanced: {
      de: "Das Upo-Feuchtgebiet (Woopo) ist das größte natürliche Binnenfeuchtgebiet Südkoreas und befindet sich im Landkreis Changnyeong. Es umfasst eine Fläche von etwa 2,13 Quadratkilometern und entstand vermutlich vor etwa 140 Millionen Jahren während der Kreidezeit. Das Gebiet besteht aus vier Hauptsümpfen: Upo, Mokpo, Sajapo und Jjokji-beol. Im Jahr 1998 wurde es als Ramsar-Gebiet ausgewiesen, was seine internationale Bedeutung für den Naturschutz unterstreicht. Das Feuchtgebiet beherbergt über 1.500 Tier- und Pflanzenarten, darunter den vom Aussterben bedrohten Japanischen Ibis, der hier erfolgreich wieder angesiedelt wurde. Geologisch gesehen ist es ein Überbleibsel des prähistorischen Nakdong-Flusslaufs. Die Wasserstände schwanken saisonal stark, was eine dynamische Umgebung für Zugvögel schafft. Upo dient heute als wichtiges Zentrum für ökologische Forschung und Umweltbildung in Ostasien.",
      hu: "Az Upo-mocsár (Woopo) Dél-Korea legnagyobb természetes belföldi vizes élőhelye, amely Changnyeong megyében található. Körülbelül 2,13 négyzetkilométeren terül el, és a feltételezések szerint 140 millió évvel ezelőtt, a kréta időszakban alakult ki. A terület négy fő mocsárból áll: Upo, Mokpo, Sajapo és Jjokji-beol. 1998-ban Ramsari területté nyilvánították, ami jelzi nemzetközi természetvédelmi jelentőségét. A vizes élőhely több mint 1500 állat- és növényfajnak ad otthont, köztük a veszélyeztetett ázsiai üstökös íbisznek, amelyet itt sikeresen visszatelepítettek. Földtanilag a terület a Nakdong-folyó ősi medrének maradványa. A vízszint szezonálisan változik, dinamikus környezetet biztosítva a vándormadaraknak. Ma az Upo-mocsár Kelet-Ázsia egyik legfontosabb ökológiai kutató- és oktatóközpontja.",
      ro: "Mlaștina Upo (Woopo) este cea mai mare zonă umedă naturală interioară din Coreea de Sud, situată în districtul Changnyeong. Se întinde pe o suprafață de aproximativ 2,13 kilometri pătrați și se crede că s-a format acum 140 de milioane de ani, în perioada Cretacicului. Zona cuprinde patru mlaștini principale: Upo, Mokpo, Sajapo și Jjokji-beol. În 1998, a fost desemnată sit Ramsar, subliniind importanța sa internațională pentru conservare. Zona umedă găzduiește peste 1.500 de specii de animale și plante, inclusiv ibisul crestat, o specie pe cale de dispariție reintrodusă cu succes aici. Din punct de vedere geologic, este o rămășiță a cursului antic al râului Nakdong. Nivelul apei variază semnificativ în funcție de sezon, creând un mediu dinamic pentru păsările migratoare. Astăzi, Upo servește ca un centru major pentru cercetarea ecologică și educația de mediu în Asia de Est.",
      en: "Upo Wetland (Woopo) is South Korea's largest natural inland wetland, located in Changnyeong County. Covering an area of approximately 2.13 square kilometers, it is estimated to have formed about 140 million years ago during the Cretaceous Period. The site consists of four main marshes: Upo, Mokpo, Sajapo, and Jjokji-beol. In 1998, it was designated as a Ramsar site, highlighting its international importance for conservation. The wetland hosts over 1,500 species of flora and fauna, including the endangered crested ibis, which was successfully reintroduced here. Geologically, the wetland is a remnant of the prehistoric Nakdong River course. Its water levels fluctuate seasonally, providing a dynamic environment for numerous migratory birds. Today, Upo serves as a critical center for ecological research and environmental education in East Asia.",
      pt: "A Zonas Húmida de Upo é a maior zona húmida natural da Coreia do Sul e está localizada na província de Gyeongsangnam-do. Abrange 8,5 km² e consiste em quatro bacias principais: Upo, Mokpo, Sajipo e Jokjibeol. Formou-se há cerca de 140 milhões de anos, no período Cretácico, através de processos geológicos. A zona húmida é um importante local de descanso para aves migratórias, incluindo grous, colhereiros e patos. Foi designada local Ramsar em 1998 e alberga mais de 1.000 espécies de flora e fauna.",
      fr: "La zone humide d'Upo est la plus grande zone humide naturelle de Corée du Sud et est située dans la province de Gyeongsangnam-do. Elle couvre 8,5 km² et se compose de quatre bassins principaux : Upo, Mokpo, Sajipo et Jokjibeol. Elle s'est formée il y a environ 140 millions d'années au Crétacé par des processus géologiques. La zone humide est un lieu de repos important pour les oiseaux migrateurs, notamment les grues, les spatules et les canards. Elle a été désignée site Ramsar en 1998 et abrite plus de 1 000 espèces de flore et de faune.",
      es: "El Humedal Upo es el humedal natural más grande de Corea del Sur y se encuentra en la provincia de Gyeongsangnam-do. Abarca 8,5 km² y consta de cuatro cuencas principales: Upo, Mokpo, Sajipo y Jokjibeol. Se formó hace unos 140 millones de años en el período Cretácico a través de procesos geológicos. El humedal es un importante lugar de descanso para aves migratorias, incluidas grullas, espátulas y patos. Fue designado sitio Ramsar en 1998 y alberga más de 1.000 especies de flora y fauna.",
    },
