      pt: ["O vale foi formado pela erosão de rocha basáltica.", "Apresenta impressionantes juntas colunares.", "Um local popular para a prática de rafting e caminhadas.", "Inclui áreas nas províncias de Gyeonggi e Gangwon."],
      fr: ["La vallée a été façonnée par l'érosion de la roche basaltique.", "Présente d'impressionnantes colonnades basaltiques.", "Un lieu prisé pour le rafting et la randonnée.", "Inclut des zones dans les provinces de Gyeonggi et Gangwon."],
